local GlassKilnMuffleMaker = {}
local PRODUCTS = {
    iron_glasskilnmuffle = { name = "Železni mufel za steklarske peči", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni mufel za steklarske peči za steklarje." },
    bronze_glasskilnmuffle = { name = "Bronast mufel za steklarske peči", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast mufel za steklarske peči za steklarje." },
    silver_glasskilnmuffle = { name = "Srebrn mufel za steklarske peči", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn mufel za steklarske peči za steklarje." },
    gilded_glasskilnmuffle = { name = "Pozlačen mufel za steklarske peči", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen mufel za steklarske peči za steklarje." },
    jewel_set_glasskilnmuffle = { name = "Draguljast mufel za steklarske peči", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast mufel za steklarske peči za steklarje." },
    royal_sovereign_glasskilnmuffle = { name = "Kraljevski suveren mufel za steklarske peči", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren mufel za steklarske peči z biseri za krono." },
}
local BUILDINGS = {
    glasskilnmuffle_workshop = { name = "Glasskilnmuffle delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    glasskilnmuffle_house = { name = "Glasskilnmuffle hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_glasskilnmuffle_atelier = { name = "Mojstrski glasskilnmuffle atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_glasskilnmuffle_palace = { name = "Suverena glasskilnmuffle palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
GlassKilnMuffleMaker.ironStock=18; GlassKilnMuffleMaker.bronzeStock=14; GlassKilnMuffleMaker.woodStock=10; GlassKilnMuffleMaker.leatherStock=8; GlassKilnMuffleMaker.silverStock=8; GlassKilnMuffleMaker.goldStock=6; GlassKilnMuffleMaker.jewelStock=4; GlassKilnMuffleMaker.pearlStock=4
GlassKilnMuffleMaker.productStock = {}; GlassKilnMuffleMaker.buildings = {}; GlassKilnMuffleMaker.maker = nil; GlassKilnMuffleMaker.activeMaking = {}; GlassKilnMuffleMaker.totalProducts = 0; GlassKilnMuffleMaker.dayTimer = 0
function GlassKilnMuffleMaker.init() GlassKilnMuffleMaker.ironStock=18; GlassKilnMuffleMaker.bronzeStock=14; GlassKilnMuffleMaker.woodStock=10; GlassKilnMuffleMaker.leatherStock=8; GlassKilnMuffleMaker.silverStock=8; GlassKilnMuffleMaker.goldStock=6; GlassKilnMuffleMaker.jewelStock=4; GlassKilnMuffleMaker.pearlStock=4; GlassKilnMuffleMaker.productStock={}; GlassKilnMuffleMaker.buildings={}; GlassKilnMuffleMaker.maker=nil; GlassKilnMuffleMaker.activeMaking={}; GlassKilnMuffleMaker.totalProducts=0; GlassKilnMuffleMaker.dayTimer=0; print("[GlassKilnMuffleMaker] Royal Glass Kiln Muffle Maker System initialized (6 products, 4 buildings)") end
function GlassKilnMuffleMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GlassKilnMuffleMaker.maker={name=n or ("Mufelničar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Mufelničar najet: %s (spretnost: %d)",GlassKilnMuffleMaker.maker.name,s),"success") end; return true end
function GlassKilnMuffleMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GlassKilnMuffleMaker.build(id) local ok,e=GlassKilnMuffleMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GlassKilnMuffleMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GlassKilnMuffleMaker.getQualityBonus() local b=0; for _,bd in ipairs(GlassKilnMuffleMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GlassKilnMuffleMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GlassKilnMuffleMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GlassKilnMuffleMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GlassKilnMuffleMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GlassKilnMuffleMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GlassKilnMuffleMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GlassKilnMuffleMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GlassKilnMuffleMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GlassKilnMuffleMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GlassKilnMuffleMaker.buildings==0 then return false,"Potrebna mufelna delavnica" end; if not GlassKilnMuffleMaker.maker then return false,"Potreben mufelničar" end; return true end
function GlassKilnMuffleMaker.make(pt,qty) qty=qty or 1; local ok,e=GlassKilnMuffleMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GlassKilnMuffleMaker.ironStock=GlassKilnMuffleMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GlassKilnMuffleMaker.bronzeStock=GlassKilnMuffleMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GlassKilnMuffleMaker.woodStock=GlassKilnMuffleMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GlassKilnMuffleMaker.leatherStock=GlassKilnMuffleMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GlassKilnMuffleMaker.silverStock=GlassKilnMuffleMaker.silverStock-d.silverCost*qty end; if d.goldCost then GlassKilnMuffleMaker.goldStock=GlassKilnMuffleMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GlassKilnMuffleMaker.jewelStock=GlassKilnMuffleMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GlassKilnMuffleMaker.pearlStock=GlassKilnMuffleMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GlassKilnMuffleMaker.maker then t=math.max(1,t-math.floor(GlassKilnMuffleMaker.maker.skill/13)) end; table.insert(GlassKilnMuffleMaker.activeMaking,{id="glasskilnmuffle_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GlassKilnMuffleMaker.completeMaking(m) local q=1.0+(GlassKilnMuffleMaker.getQualityBonus()/100); if GlassKilnMuffleMaker.maker then q=q+(GlassKilnMuffleMaker.maker.skill/140) end; q=math.min(2.5,q); GlassKilnMuffleMaker.productStock[m.productType]=(GlassKilnMuffleMaker.productStock[m.productType] or 0)+m.quantity; GlassKilnMuffleMaker.totalProducts=GlassKilnMuffleMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GlassKilnMuffleMaker.maker then GlassKilnMuffleMaker.maker.itemsMade=GlassKilnMuffleMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GlassKilnMuffleMaker.maker.skill=math.min(100,GlassKilnMuffleMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Mufel izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"glasskilnmuffle.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GlassKilnMuffleMaker.update(dt) if not _G.state then return end; GlassKilnMuffleMaker.dayTimer=GlassKilnMuffleMaker.dayTimer+dt; if GlassKilnMuffleMaker.dayTimer>=30 then GlassKilnMuffleMaker.dayTimer=0; for i=#GlassKilnMuffleMaker.activeMaking,1,-1 do local m=GlassKilnMuffleMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GlassKilnMuffleMaker.completeMaking(m); table.remove(GlassKilnMuffleMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GlassKilnMuffleMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GlassKilnMuffleMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GlassKilnMuffleMaker.getStats() return {ironStock=GlassKilnMuffleMaker.ironStock,bronzeStock=GlassKilnMuffleMaker.bronzeStock,woodStock=GlassKilnMuffleMaker.woodStock,leatherStock=GlassKilnMuffleMaker.leatherStock,silverStock=GlassKilnMuffleMaker.silverStock,goldStock=GlassKilnMuffleMaker.goldStock,jewelStock=GlassKilnMuffleMaker.jewelStock,pearlStock=GlassKilnMuffleMaker.pearlStock,productStock=GlassKilnMuffleMaker.productStock,numBuildings=#GlassKilnMuffleMaker.buildings,hasMaker=GlassKilnMuffleMaker.maker~=nil,makerName=GlassKilnMuffleMaker.maker and GlassKilnMuffleMaker.maker.name or "—",makerSkill=GlassKilnMuffleMaker.maker and GlassKilnMuffleMaker.maker.skill or 0,activeMaking=#GlassKilnMuffleMaker.activeMaking,totalProducts=GlassKilnMuffleMaker.totalProducts} end
return GlassKilnMuffleMaker
